"""`.Tex Face misc`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Tex Face misc'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Main texture', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Main texture (alpha)', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Kage texture', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Kage texture (alpha)', 'NodeSocketFloat')
    t.socket('OUTPUT', 'Down texture', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Down texture (alpha)', 'NodeSocketFloat')
    t.socket('OUTPUT', 'Toon shading', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeFrame', 'Node', props={
        'location': (-805.0, -250.0),
        'width': 555.8114,
        'label': 'Permalight mask (R = light, B = dark, dark takes priority)',
        'use_custom_color': True,
        'color': (0.47511104, 0.45669952, 0.33585504),
    })
    t.node('ShaderNodeTexImage', 'perma', parent='Node', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (30.17389, -45.258972),
        'width': 495.81143,
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (232.48726, 114.04353),
    })
    t.node('ShaderNodeGroup', 'shade', props={
        'node_tree': lib.group('.Toon shading'),
        'location': (-62.116043, -95.20957),
        'width': 247.78687,
    })
    t.node('ShaderNodeTexImage', '_ST_CT.png', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (-270.67236, 83.17699),
        'width': 346.60596,
        'label': 'main texture',
        'hide': True,
        'show_texture': True,
    })
    t.node('ShaderNodeTexImage', '_ST_CT.pngkage', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (-270.67236, 29.381002),
        'width': 346.60596,
        'label': 'kage texture',
        'hide': True,
    })
    t.node('ShaderNodeTexImage', '_ST_CT.pngdown', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (-270.67236, -13.487696),
        'width': 346.60596,
        'label': 'down texture',
        'hide': True,
    })

    t.link('_ST_CT.png', 'Color', 'Group Output', 'Main texture')
    t.link('_ST_CT.png', 'Alpha', 'Group Output', 'Main texture (alpha)')
    t.link('perma', 'Color', 'shade', 'Permalight mask')
    t.link('shade', 'Toon shading', 'Group Output', 'Toon shading')
    t.link('_ST_CT.pngkage', 'Color', 'Group Output', 'Kage texture')
    t.link('_ST_CT.pngkage', 'Alpha', 'Group Output', 'Kage texture (alpha)')
    t.link('_ST_CT.pngdown', 'Color', 'Group Output', 'Down texture')
    t.link('_ST_CT.pngdown', 'Alpha', 'Group Output', 'Down texture (alpha)')
    return t
